/usr/bin/zsh -lc "cat > candidate.sv <<'EOF'
module TopModule (
    input  logic       in,
    input  logic [3:0] state,
    output logic [3:0] next_state,
    output logic       out
);
    assign next_state[0] = ~in & (state[0] | state[2]);
    assign next_state[1] =  in & (state[0] | state[1] | state[3]);
    assign next_state[2] = ~in & (state[1] | state[3]);
    assign next_state[3] =  in & state[2];
    assign out = state[3];
endmodule
EOF
cp candidate.sv candidate_initial.sv
cat > dev_tb.sv <<'EOF'
module dev_tb;
    logic in;
    logic [3:0] state;
    wire [3:0] next_state;
    wire out;
    logic [3:0] expected;
    TopModule dut (.in(in), .state(state), .next_state(next_state), .out(out));
    initial begin
        for (integer s = 0; s < 4; s = s + 1) begin
            for (integer i = 0; i < 2; i = i + 1) begin
                state = 4'b0001 << s;
                in = (i == 1);
                case (s)
                    0: expected = in ? 4'b0010 : 4'b0001;
                    1: expected = in ? 4'b0010 : 4'b0100;
                    2: expected = in ? 4'b1000 : 4'b0001;
                    3: expected = in ? 4'b0010 : 4'b0100;
                endcase
                #1;
                if (next_state "'!== expected || out !== (s == 3))
                    $fatal(1, "FAIL state=%b in=%b next=%b expected=%b out=%b", state, in, next_state, expected, out);
            end
        end
        $display("PASS: all 8 one-hot state/input combinations");
        $finish;
    end
    initial begin
        #100;
        $fatal(1, "FAIL: development simulation timeout");
    end
endmodule
EOF
timeout 20s /home/shmin/nl2hdl/.conda_pkgs/iverilog-12.0-ha738cfc_1/bin/iverilog -g2012 -Wall -s dev_tb -o dev_sim candidate.sv dev_tb.sv > dev_compile.log 2>&1'

